            );
        }
        for q in 10..110 {
            e.insert(
                q,
                json!({"question/difficulty":if q == 10 {1} else if q == 11 {2} else {3}})
                    .as_object()
                    .unwrap()
                    .clone(),
            );
        }
        e.insert(200, serde_json::Map::new());
        EntitySnapshot::new(e, 1).unwrap()
    }

    #[test]
    fn draws_bands_before_questions_and_is_stable() {
        let s = snapshot();
        let pool: Vec<_> = (10..110).collect();
        let mut counts = [0; 3];
        for trial in 0..10000 {
            let seed = trial.to_string();
            let q = select(&s, &pool, Some([6.0, 3.0, 1.0]), &seed)
                .unwrap()
                .unwrap();
            assert_eq!(
                Some(q),
                select(&s, &pool, Some([6.0, 3.0, 1.0]), &seed).unwrap()
            );
            counts[if q == 10 {
                0
            } else if q == 11 {
                1
            } else {
                2
            }] += 1;
        }
        for (count, expected) in counts.into_iter().zip([6000i32, 3000, 1000]) {
            assert!((count - expected).abs() < 200, "{counts:?}");
        }
    }

    #[test]
    fn missing_supply_renormalizes_without_using_excluded_bands_or_inventing_ratings() {
        let s = snapshot();
        assert_eq!(
            select(&s, &[11, 12, 200], Some([6.0, 3.0, 0.0]), "x").unwrap(),
            Some(11)
        );
        assert_eq!(
            select(&s, &[12, 200], Some([6.0, 3.0, 0.0]), "x").unwrap(),
            Some(200)
        );
        assert_eq!(select(&s, &[12], Some([6.0, 3.0, 0.0]), "x").unwrap(), None);
        assert!(select(&s, &[10], Some([0.0; 3]), "x").is_err());
    }

    #[test]
    fn phases_and_activity_types_are_independent_and_bad_configuration_fails() {
        let mut s = snapshot();
        for (id, kind) in [(300, "lesson"), (301, "review"), (302, "assessment")] {
            s.entities.insert(
                id,
                json!({"db/ident":{"$keyword":format!("activity.type/{kind}")}})
                    .as_object()
                    .unwrap()
                    .clone(),
            );
            s.entities.insert(id+10, json!({"question-weights/activity-type":id,
                "question-weights/initial-easy":1.0,"question-weights/initial-moderate":2.0,"question-weights/initial-hard":3.0,
                "question-weights/remedial-easy":4.0,"question-weights/remedial-moderate":5.0,"question-weights/remedial-hard":0.0}).as_object().unwrap().clone());
        }
        s.entities.insert(
            400,
            json!({"policy/question-selection-weights":[310,311,312]})
                .as_object()
                .unwrap()
                .clone(),
        );
        assert_eq!(
            weights(&s, 400, "lesson", 1).unwrap(),
            Some([1.0, 2.0, 3.0])
        );
        assert_eq!(
            weights(&s, 400, "lesson", 2).unwrap(),
            Some([4.0, 5.0, 0.0])
        );
        assert_eq!(
            weights(&s, 400, "review", 2).unwrap(),
            Some([1.0, 2.0, 3.0])
        );
        assert_eq!(
            weights(&s, 400, "review", 3).unwrap(),
            Some([4.0, 5.0, 0.0])
        );
        assert_eq!(
            weights_for_phase(&s, 400, "assessment", Phase::Initial).unwrap(),
            Some([1.0, 2.0, 3.0])
        );
        assert_eq!(
            weights_for_phase(&s, 400, "assessment", Phase::Remedial).unwrap(),
            Some([4.0, 5.0, 0.0])
        );
        assert!(weights(&s, 400, "assessment", 100).is_err());
        let good = s.clone();
        // Even unused assessment remedial weights must be valid.
        s.entities
            .get_mut(&312)
            .unwrap()
            .remove("question-weights/remedial-hard");
        assert!(weights(&s, 400, "lesson", 0).is_err());
        s = good.clone();
        for band in BANDS {
            s.entities
                .get_mut(&312)
                .unwrap()
                .insert(format!("question-weights/remedial-{band}"), json!(0.0));
        }
        assert!(weights_for_phase(&s, 400, "assessment", Phase::Initial).is_err());
        s = good.clone();
        let duplicate = s.entities[&312].clone();
        s.entities.insert(313, duplicate);
        s.entities.get_mut(&400).unwrap().insert(
            "policy/question-selection-weights".into(),
            json!([310, 311, 312, 313]),
        );
        assert!(weights_for_phase(&s, 400, "assessment", Phase::Initial).is_err());
        s = good.clone();
        s.entities.insert(
            401,
            json!({"policy/question-selection-weights":[312]})
                .as_object()
                .unwrap()
                .clone(),
        );
        assert!(weights_for_phase(&s, 400, "assessment", Phase::Initial).is_err());
        s = good;
        s.entities
            .get_mut(&311)
            .unwrap()
            .insert("question-weights/remedial-easy".into(), json!(-1.0));
        assert!(weights(&s, 400, "lesson", 0).is_err());
    }
